function safeArrayParse(val) {
  if (!val) return "";
  if (Array.isArray(val)) return val.join(", ");

  if (typeof val === "string") {
    try {
      const cleaned = val.replace(/^"|"$/g, "");
      const parsed = JSON.parse(cleaned);
      if (Array.isArray(parsed)) return parsed.join(", ");
    } catch (e) {}
  }
  return val;
}

